const PRODUCT_IMAGE_MAX_SIDE = 1200;
const PRODUCT_IMAGE_TARGET_BYTES = 360_000;

async function compressProductImage(file: File): Promise<string> {
  const source = URL.createObjectURL(file);
  try {
    const image = new Image();
    image.src = source;
    await new Promise<void>((resolve, reject) => { image.onload = () => resolve(); image.onerror = () => reject(new Error('تعذر قراءة صورة المنتج')); });
    const scale = Math.min(1, PRODUCT_IMAGE_MAX_SIDE / Math.max(image.naturalWidth, image.naturalHeight));
    const canvas = document.createElement('canvas');
    canvas.width = Math.max(1, Math.round(image.naturalWidth * scale));
    canvas.height = Math.max(1, Math.round(image.naturalHeight * scale));
    const context = canvas.getContext('2d');
    if (!context) throw new Error('تعذر تجهيز الصورة للضغط');
    context.fillStyle = '#ffffff';
    context.fillRect(0, 0, canvas.width, canvas.height);
    context.drawImage(image, 0, 0, canvas.width, canvas.height);
    const supportsWebP = canvas.toDataURL('image/webp').startsWith('data:image/webp');
    const mime = supportsWebP ? 'image/webp' : 'image/jpeg';
    let quality = 0.76;
    let output = canvas.toDataURL(mime, quality);
    while (output.length * 0.75 > PRODUCT_IMAGE_TARGET_BYTES && quality > 0.46) {
      quality -= 0.06;
      output = canvas.toDataURL(mime, quality);
    }
    return output;
  } finally { URL.revokeObjectURL(source); }
}

